package network.vonix.serverutilities.platform;
import com.mojang.brigadier.CommandDispatcher; import net.minecraft.commands.CommandSourceStack; import net.minecraft.server.MinecraftServer; import net.minecraft.server.level.ServerPlayer; import net.minecraft.world.damagesource.DamageSource; import net.minecraft.world.entity.LivingEntity; import java.nio.file.Path; import java.util.function.*;
public interface PlatformEvents { void register(Callbacks c); Path configDirectory(); boolean easyNpcInstalled(); void registerEasyNpcInteraction(); void openAccessoryMenu(ServerPlayer t,ServerPlayer v); record Callbacks(Consumer<CommandDispatcher<CommandSourceStack>> commands,Consumer<MinecraftServer> serverStarting,Consumer<MinecraftServer> serverStarted,Consumer<MinecraftServer> serverStopping,Consumer<MinecraftServer> serverStopped,Consumer<MinecraftServer> serverTick,Consumer<ServerPlayer> playerJoin,Consumer<ServerPlayer> playerQuit,BiConsumer<LivingEntity,DamageSource> livingDeath){} final class Holder{private static PlatformEvents instance;public static void install(PlatformEvents v){instance=v;}public static PlatformEvents get(){if(instance==null)throw new IllegalStateException("VSU loader platform was not installed");return instance;}}}
